using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class CareerMilitaryTests
{
    static WorldSession New()=>new(CareerMilitary.Create());
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static void Open(WorldSession s,string id)=>Assert.Equal(ResultCode.Accepted,s.Open(s.PlayerControl,new(id),s.Revision).Code);
    static long Due(WorldSession s,string id)=>MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,id).DueAt;
    static void Join(WorldSession s){var id=new EntityId("request:join");Assert.Equal(ResultCode.Accepted,s.DecideCareer(new(id,CareerAction.Apply),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s,s.DiagnosticSnapshot().Career!.Events.Single(e=>e.Kind==CareerEventKind.Offered).Message);Assert.Equal(ResultCode.Accepted,s.DecideCareer(new(new("request:join-answer"),CareerAction.Accept,id),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Open(s,s.DiagnosticSnapshot().Career!.Events.Single(e=>e.Kind==CareerEventKind.Joined).Message);var work=RegionalWork.Inbox(s).Last(c=>c.CanOpen);Open(s,work.Message.Value);At(s,s.Seconds+5);}
    static MilitaryInput Input(MilitaryAction action)=>new(new("request:military/"+action),action);
    static void Decide(WorldSession s,MilitaryAction action)=>Assert.Equal(ResultCode.Accepted,s.DecideMilitary(Input(action),s.PlayerControl,s.Revision).Code);
    static string Notice(WorldSession s,MilitaryEffect effect)=>s.DiagnosticSnapshot().Military!.Events.Single(e=>e.Effect==effect).Message;
    static void Permission(WorldSession s){Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Offered));Decide(s,MilitaryAction.Accept);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Permission));}
    static void Pickup(WorldSession s){Permission(s);Decide(s,MilitaryAction.Pickup);}
    [Fact]public void InitialRoninHasNoCommandOrSupplyPermission(){var s=New();var w=s.DiagnosticSnapshot();Assert.Empty(w.CommandMandates!);Assert.False(CareerMilitary.Custody(w));Assert.All(w.Units.Where(u=>FieldWorld.UnitIds.Contains(u.Id)),u=>Assert.Equal(RetainerStart.Lord,u.Commander));Assert.Equal(ResultCode.NotAvailable,s.HandleSupply(new("request:free-supply"),s.PlayerControl,true,1,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);}
    [Fact]public void ServiceAloneCannotDeployOrTakeStock(){var s=New();Join(s);Assert.True(Career.ActiveAt(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds));Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.HandleSupply(new("request:free"),s.PlayerControl,true,100,s.Revision).Code);Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);}
    [Fact]public void UnopenedConditionsCannotBeAnswered(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideMilitary(Input(MilitaryAction.Accept),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void ReceivedPermissionStillRequiresLocalPickup(){var s=New();Permission(s);Assert.True(CareerMilitary.View(s,s.PlayerControl).CanPickup);Assert.False(CareerMilitary.Custody(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.NotAvailable,s.SetRegionalActive(true,s.Revision).Code);var p=s.GetBranchView(s.PlayerControl).Position;Decide(s,MilitaryAction.Pickup);Assert.Equal(p,s.GetBranchView(s.PlayerControl).Position);Assert.All(s.DiagnosticSnapshot().Units.Where(u=>FieldWorld.UnitIds.Contains(u.Id)),u=>Assert.Equal(s.PlayerControl,u.Commander));}
    [Fact]public void DuplicatePickupIsIdempotentAndOtherActorsCannotTakeCommand(){var s=New();Pickup(s);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.AlreadyAccepted,s.DecideMilitary(Input(MilitaryAction.Pickup),s.PlayerControl,0).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideMilitary(Input(MilitaryAction.Pickup) with{Action=MilitaryAction.Return},s.PlayerControl,s.Revision).Code);Assert.Equal(ResultCode.NotAvailable,s.DecideMilitary(new(new("request:stolen"),MilitaryAction.Return),RetainerStart.Lord,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void PickupDeployAndReturnDoNotTeleportTheOfficer(){var s=New();Pickup(s);var p=s.GetBranchView(s.PlayerControl).Position;Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,FieldSupply.Capacity,s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);Assert.Equal(p,s.GetBranchView(s.PlayerControl).Position);At(s,s.Seconds+3);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(false,s.Revision).Code);Assert.Equal(p,s.GetBranchView(s.PlayerControl).Position);Assert.Equal(FieldSupply.Capacity-300,FieldSupply.Carried(s.DiagnosticSnapshot()).Quantity);}
    [Fact]public void NoEngagementGrantExistsEvenAfterPickup(){var s=New();Pickup(s);Assert.DoesNotContain(RegionalAction.Engage,s.DiagnosticSnapshot().CommandMandates!.Single().Actions);Assert.False(EngagementMission.CanEngage(s.DiagnosticSnapshot(),new(new("request:attack"),s.PlayerControl,s.PlayerControl,RegionalAction.Engage,new(0,0),new(10000,0)),s.Seconds));}
    [Fact]public void PhysicalReturnWaitsForReportAndStockBeforeEndingCustody(){var s=New();Pickup(s);Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:pack"),s.PlayerControl,true,1000,s.Revision).Code);Decide(s,MilitaryAction.Return);At(s,s.Seconds+2);Assert.Contains(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Waiting);Assert.True(CareerMilitary.Custody(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,s.ReportEngagement(new("request:report"),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Assert.True(CareerMilitary.Custody(s.DiagnosticSnapshot()));Assert.Equal(ResultCode.Accepted,s.HandleSupply(new("request:stock-return"),s.PlayerControl,false,1000,s.Revision).Code);var p=s.GetBranchView(s.PlayerControl).Position;At(s,s.Seconds+1);Assert.False(CareerMilitary.Custody(s.DiagnosticSnapshot()));Assert.Equal(p,s.GetBranchView(s.PlayerControl).Position);ContractValidation.Validate(s.DiagnosticSnapshot());Assert.All(s.DiagnosticSnapshot().Units.Where(u=>FieldWorld.UnitIds.Contains(u.Id)),u=>Assert.Equal(RetainerStart.Lord,u.Commander));}
    [Fact]public void ResignationWaitsForBorrowedCommandAndThenContinuesSameLife(){var s=New();Pickup(s);var identity=s.PlayerControl;var world=s.DiagnosticSnapshot().WorldId;Assert.Equal(ResultCode.Accepted,s.DecideCareer(new(new("request:release"),CareerAction.RequestRelease,new("request:join")),s.PlayerControl,s.Revision).Code);At(s,s.Seconds+2);Assert.True(Career.ActiveAt(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds));Assert.Equal(ResultCode.Accepted,s.ReportEngagement(new("request:report"),s.PlayerControl,s.Revision).Code);Decide(s,MilitaryAction.Return);At(s,s.Seconds+3);Assert.False(Career.ActiveAt(s.DiagnosticSnapshot(),RetainerStart.Lord,s.Seconds));Assert.Equal(identity,s.PlayerControl);Assert.Equal(world,s.DiagnosticSnapshot().WorldId);ContractValidation.Validate(s.DiagnosticSnapshot());}
    [Theory][InlineData(false)][InlineData(true)]public void RestoreAndSameContinuationPreserveFullWorld(bool pickup){var s=New();Permission(s);if(pickup)Decide(s,MilitaryAction.Pickup);s.SetPaused(true);var store=new GenerationSaveStore(Path.Combine(Path.GetTempPath(),"military-"+Guid.NewGuid().ToString("N")),s.DiagnosticSnapshot().Definitions);store.Save(s,"state",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(New());Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("state"),host.Current,host.Current.Revision));At(s,s.Seconds+3);At(host.Current,s.Seconds);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(host.Current.DiagnosticSnapshot()));}
    [Fact]public void LostAcceptanceCannotGrantCommand(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Offered));Decide(s,MilitaryAction.Accept);var id=s.DiagnosticSnapshot().Military!.Requests.Last().Message!;s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,id));At(s,s.Seconds+125);Assert.DoesNotContain(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Permission);Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);}
    [Fact]public void OldCareerLiteralJsonIsStillAccepted(){foreach(var name in new[]{"initial","unconfirmed"}){var bytes=File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","career-72b0665-"+name+".json"));var w=ContractJson.Read<ContractWorld>(bytes);ContractValidation.Validate(w);Assert.Null(w.Military);Assert.Equal(bytes,ContractJson.Write(w));}}
    [Theory][InlineData("mandate")][InlineData("owner")][InlineData("notice")][InlineData("opening")][InlineData("commander")]
    public void ForgedMilitaryStateCannotLoad(string kind){var s=New();Pickup(s);var w=s.DiagnosticSnapshot();if(kind=="mandate")w.CommandMandates![0]=w.CommandMandates[0] with{Actions=[RegionalAction.Move,RegionalAction.Engage]};if(kind=="owner")w.Units=w.Units.Select(u=>FieldWorld.UnitIds.Contains(u.Id)?u with{Organization=w.PlayerControl}:u).ToArray();if(kind=="notice"){var id=Notice(s,MilitaryEffect.Permission);w.Messaging.Messages=w.Messaging.Messages.Select(m=>m.Id==id?m with{Body="{}"}:m).ToArray();}if(kind=="opening")w.Military=w.Military! with{Openings=w.Military.Openings.Select(o=>o with{Revision=w.CommitSequence+1}).ToArray()};if(kind=="commander")w.Units=w.Units.Select(u=>FieldWorld.UnitIds.Contains(u.Id)?u with{Commander=RetainerStart.Lord}:u).ToArray();Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}

    [Fact]public void AcceptanceDeadlineUsesPrincipalReceipt(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Offered));long expiry=s.DiagnosticSnapshot().Military!.Events.Single(e=>e.Effect==MilitaryEffect.Offered).At+CareerMilitary.OfferSeconds;At(s,expiry-1);Decide(s,MilitaryAction.Accept);At(s,expiry+1);Assert.DoesNotContain(s.DiagnosticSnapshot().Military!.Events,e=>e.Effect==MilitaryEffect.Permission);Assert.Equal(AttemptStatus.Rejected,MessageFlow.Latest(s.DiagnosticSnapshot().Messaging,s.DiagnosticSnapshot().Military!.Requests.Last().Message!).Status);}
    [Fact]public void OpenedPermissionCannotBePickedUpFromAnotherSite(){var s=New();Permission(s);Assert.Equal(ResultCode.Accepted,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),"request:away-before-pickup","kofu"),s.Revision).Code);At(s,s.Seconds+2);var before=ContractJson.Write(s.DiagnosticSnapshot());Assert.Equal(ResultCode.NotAvailable,s.DecideMilitary(Input(MilitaryAction.Pickup),s.PlayerControl,s.Revision).Code);Assert.Equal(before,ContractJson.Write(s.DiagnosticSnapshot()));}
    [Fact]public void RemoteFormationWithoutPersonalDeploymentIsRefused(){var s=New();Pickup(s);var r=new RegionalRequest(new("request:remote-line"),s.PlayerControl,s.PlayerControl,RegionalAction.Move,new(0,0),new(10000,0));Assert.False(CreatedCampaign.CanCommand(s.DiagnosticSnapshot(),r,s.Seconds));}
    [Fact]public void MilitaryRequestIdCannotBeUsedForTravelOrCareer(){var s=New();Join(s);Decide(s,MilitaryAction.Request);var id=Input(MilitaryAction.Request).Id;Assert.Equal(ResultCode.IdPayloadConflict,s.Submit(TravelWorld.Move(s.DiagnosticSnapshot(),id.Value,"kofu"),s.Revision).Code);Assert.Equal(ResultCode.IdPayloadConflict,s.DecideCareer(new(id,CareerAction.Inquire,new("request:join")),s.PlayerControl,s.Revision).Code);}
    [Fact]public void LostPermissionRemainsUnknownAndDoesNotTransferCommand(){var s=New();Join(s);Decide(s,MilitaryAction.Request);At(s,s.Seconds+2);Open(s,Notice(s,MilitaryEffect.Offered));Decide(s,MilitaryAction.Accept);At(s,s.Seconds+1);string notice=Notice(s,MilitaryEffect.Permission);s.DiagnosticTransport((m,t)=>MessageFlow.Fail(m,notice));At(s,s.Seconds+2);Assert.False(CareerMilitary.View(s,s.PlayerControl).CanPickup);Assert.Empty(s.DiagnosticSnapshot().CommandMandates!);Assert.False(MessageFlow.Knows(s.DiagnosticSnapshot().Messaging,notice,s.PlayerControl.Value));}
}
